function configuredPublicBase(){
  const explicit=String(process.env.PUBLIC_BASE_URL||'').trim().replace(/\/$/,'');
  if(explicit)return explicit;
  const renderHost=String(process.env.RENDER_EXTERNAL_HOSTNAME||'').trim();
  return renderHost?`https://${renderHost}`:'';
}
function validateProductionConfig(){
  if(process.env.NODE_ENV!=='production')return;
  const errors=[];
  if(PERSONAL_MODE){
    const email=normalizeEmail(process.env.PERSONAL_EMAIL);
    const password=String(process.env.PERSONAL_PASSWORD||'');
    if(!email)errors.push('PERSONAL_EMAIL_required');
    if(password.length<16)errors.push('PERSONAL_PASSWORD_must_have_16_chars_in_production');
    if(['FlowPilot123!','FlowPilotPersonal123!'].includes(password))errors.push('PERSONAL_PASSWORD_default_forbidden');
  }
  if((process.env.STORAGE_DRIVER||'json')!=='postgres')errors.push('STORAGE_DRIVER_must_be_postgres_in_production');
  if(!process.env.DATABASE_URL)errors.push('DATABASE_URL_required');
  if(String(process.env.APP_ENCRYPTION_KEY||'').length<32)errors.push('APP_ENCRYPTION_KEY_must_have_32_chars');
  const base=configuredPublicBase();
  if(!base.startsWith('https://'))errors.push('PUBLIC_BASE_URL_or_RENDER_EXTERNAL_HOSTNAME_must_use_https');
  if(PERSONAL_MODE&&!SETUP_MODE&&(!process.env.INSTAGRAM_APP_ID||!process.env.INSTAGRAM_APP_SECRET))errors.push('INSTAGRAM_APP_credentials_required_unless_SETUP_MODE');
  if(PERSONAL_MODE&&!process.env.META_WEBHOOK_VERIFY_TOKEN)errors.push('META_WEBHOOK_VERIFY_TOKEN_required');
  if(errors.length)throw new Error(`production_config_invalid:${errors.join(',')}`);
}
function applySecurityHeaders(req,res){
  res.setHeader('x-content-type-options','nosniff');res.setHeader('x-frame-options','DENY');res.setHeader('referrer-policy','no-referrer');res.setHeader('permissions-policy','camera=(), microphone=(), geolocation=()');
  res.setHeader('content-security-policy',"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self' https://graph.facebook.com https://graph.instagram.com https://api.telegram.org; img-src 'self' data:; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");
  if(String(req.headers['x-forwarded-proto']||'').split(',')[0].trim()==='https')res.setHeader('strict-transport-security','max-age=31536000; includeSubDomains');
}
function json(res,status,data,headers={}){const body=JSON.stringify(data);res.writeHead(status,{'content-type':'application/json; charset=utf-8','content-length':Buffer.byteLength(body),'cache-control':'no-store',...headers});res.end(body)}
function redirect(res,location,status=302){res.writeHead(status,{location,'cache-control':'no-store'});res.end()}
