function serveStatic(req,res){const file=safeFile(new URL(req.url,'http://localhost').pathname);if(!file||!fs.existsSync(file)||fs.statSync(file).isDirectory())return false;const ext=path.extname(file),types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json; charset=utf-8','.svg':'image/svg+xml'};res.writeHead(200,{'content-type':types[ext]||'application/octet-stream','cache-control':ext==='.html'?'no-store':'public, max-age=300'});fs.createReadStream(file).pipe(res);return true}
function isSecure(req){return String(req.headers['x-forwarded-proto']||'').split(',')[0].trim()==='https'}
function publicUser(u){return u?{id:u.id,email:u.email,name:u.name,createdAt:u.createdAt||u.created_at}:null}
function redactedConnection(c){if(!c)return null;return{id:c.id,provider:c.provider,providerAccountId:c.providerAccountId||c.provider_account_id,status:c.status,metadata:c.metadata||{},createdAt:c.createdAt||c.created_at,updatedAt:c.updatedAt||c.updated_at}}
function checksum(value){return crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex')}
function sameOrigin(req){const origin=req.headers.origin;if(!origin)return true;try{const o=new URL(origin);return o.host===req.headers.host}catch{return false}}
function limitResponse(res,r){return json(res,429,{error:'rate_limit_exceeded',retryAfterSeconds:Math.ceil(r.retryAfterMs/1000)},{'retry-after':String(Math.ceil(r.retryAfterMs/1000)),'x-ratelimit-limit':String(r.limit),'x-ratelimit-remaining':String(r.remaining)})}
